-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------

-- Trims and collapses whitespace in station names; empty becomes NULL.
CREATE OR REPLACE FUNCTION public.canonicalize_personnel_station() RETURNS trigger AS $$
BEGIN
  NEW.school   := NULLIF(btrim(regexp_replace(NEW.school,   '[ \t\n\r\f\v]+', ' ', 'g')), '');
  NEW.district := NULLIF(btrim(regexp_replace(NEW.district, '[ \t\n\r\f\v]+', ' ', 'g')), '');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER personnel_canonical_station
  BEFORE INSERT OR UPDATE OF school, district ON public.personnel
  FOR EACH ROW EXECUTE FUNCTION public.canonicalize_personnel_station();

-- Fills category, target_type/target_id, outcome and severity when an older
-- write site leaves them out. Full body: migration 202609280001_audit_trail_hardening.
CREATE TRIGGER validation_logs_canonical_defaults
  BEFORE INSERT ON public.validation_logs
  FOR EACH ROW EXECUTE FUNCTION public.validation_logs_fill_canonical_defaults();

